css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #018E34; text-decoration: none; }
.dcx a:hover{ color: #016E28; }
.dcx :focus-visible{ outline: 2px solid #2FCB74; outline-offset: 3px; }
@keyframes nc-sky{
    0%   { transform: scale(1.05) translate(0, 0); }
    50%  { transform: scale(1.11) translate(-1.4%, 1.2%); }
    100% { transform: scale(1.05) translate(0, 0); }
  }
@keyframes nc-twinkle{
    0%, 100% { opacity: .35; }
    50%      { opacity: .95; }
  }
@keyframes nc-drift{
    0%   { transform: translate3d(0, 0, 0); }
    100% { transform: translate3d(0, -22px, 0); }
  }
@media (prefers-reduced-motion: reduce){.dcx [data-sky],.dcx [data-stars]{ animation: none !important; }
}
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-two],.dcx [data-story],.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-cta]{ padding: 0 44px !important; }
.dcx [data-cta] > ul{ padding-right: 0 !important; }
.dcx [data-rail]{ grid-template-columns: repeat(5, minmax(0,1fr)) !important; }
.dcx [data-sum],.dcx [data-qs],.dcx [data-ind]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-split]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 30px !important; }
}
@media (max-width: 640px){.dcx [data-rail]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-sum],.dcx [data-qs],.dcx [data-ind]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 31px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
.dcx [data-cta]{ padding: 0 20px !important; }
}
